#define wWinMain unused_gui_entry
#include "../src/gui.cpp"
#undef wWinMain
#include <iostream>
std::wstring Env(const wchar_t*n){wchar_t b[256]{};GetEnvironmentVariableW(n,b,256);return b;}
int Fake(int argc,wchar_t**argv){HANDLE pipe=nullptr,event=nullptr;bool wu=false,local=false,full=false,online=false;for(int i=1;i<argc;++i){std::wstring a=argv[i];if(a==L"--pipe")pipe=(HANDLE)uintptr_t(std::stoull(argv[++i]));else if(a==L"--cancel-handle")event=(HANDLE)uintptr_t(std::stoull(argv[++i]));else if(a==L"--windows-update")wu=true;else if(a==L"--local-only")local=true;else if(a==L"--full-payload")full=true;else if(a==L"--online")online=true;}
 HANDLE sem=OpenSemaphoreW(SEMAPHORE_MODIFY_STATE,FALSE,Env(L"ADISM_POLICY_COUNTER").c_str());if(sem){ReleaseSemaphore(sem,1,nullptr);CloseHandle(sem);}int mode=_wtoi(Env(L"ADISM_POLICY_CASE").c_str());bool good=full&&online&&(mode==0?wu&&!local:mode==1?local&&!wu:!local&&!wu);
 std::string bytes="R\t"+std::string(good?"0x00000000":"0x80070057")+"\t-1\t0\t0\ttest\tpolicy checked\t\t0\t1\n";DWORD n=0;WriteFile(pipe,bytes.data(),DWORD(bytes.size()),&n,nullptr);if(mode==4)WriteFile(pipe,bytes.data(),DWORD(bytes.size()),&n,nullptr);if(mode==5)WriteFile(pipe,"tail",4,&n,nullptr);CloseHandle(pipe);CloseHandle(event);if(mode==3){Sleep(100);return 1;}return good?0:1;}
int wmain(int argc,wchar_t**argv){for(int i=1;i<argc;++i)if(std::wstring(argv[i])==L"--cbs-worker")return Fake(argc,argv);int cases=0,failures=0;auto check=[&](bool ok,const char*n){++cases;std::cout<<n<<"="<<ok<<std::endl;if(!ok)++failures;};auto key=L"Local\\ADismPolicy-"+std::to_wstring(GetCurrentProcessId());HANDLE sem=CreateSemaphoreW(nullptr,0,20,key.c_str());SetEnvironmentVariableW(L"ADISM_POLICY_COUNTER",key.c_str());
 for(int mode=0;mode<3;++mode){SetEnvironmentVariableW(L"ADISM_POLICY_CASE",std::to_wstring(mode).c_str());servicing::CbsOptions o;o.operation=servicing::CbsOperation::Restore;o.sourceKind=mode==0?servicing::RepairSourceKind::WindowsUpdate:mode==1?servicing::RepairSourceKind::LocalOnly:servicing::RepairSourceKind::Default;cancelled=false;auto r=IsolatedCbs(o);check(r.hr==S_OK&&WaitForSingleObject(sem,0)==WAIT_OBJECT_0,mode==0?"WU-roundtrip":mode==1?"LocalOnly-roundtrip":"Default-roundtrip");}
 for(int mode=3;mode<=5;++mode){SetEnvironmentVariableW(L"ADISM_POLICY_CASE",std::to_wstring(mode).c_str());servicing::CbsOptions o;o.operation=servicing::CbsOperation::Restore;cancelled=false;auto r=IsolatedCbs(o);check(r.hr!=S_OK&&r.imageStateUnknown,mode==3?"abnormal-worker-exit-rejected":mode==4?"duplicate-result-rejected":"partial-tail-rejected");WaitForSingleObject(sem,0);}
 cancelled=true;auto stopped=IsolatedCbs({});check(stopped.hr==HRESULT_FROM_WIN32(ERROR_CANCELLED)&&WaitForSingleObject(sem,0)==WAIT_TIMEOUT,"pre-cancel-no-worker");cancelled=false;
 for(int mode=0;mode<2;++mode){SECURITY_ATTRIBUTES sa{sizeof(sa),nullptr,TRUE};HANDLE rd=nullptr,wr=nullptr;CreatePipe(&rd,&wr,&sa,0);HANDLE event=CreateEventW(&sa,TRUE,TRUE,nullptr);std::vector<std::wstring> a={L"test",L"--pipe",std::to_wstring(uintptr_t(wr)),L"--cancel-handle",std::to_wstring(uintptr_t(event)),L"--windows-update",mode==0?L"--local-only":L"--source-directory"};if(mode==1)a.push_back(L"D:\\Windows");std::vector<wchar_t*> pointers;for(auto&s:a)pointers.push_back(s.data());int result=Worker(int(pointers.size()),pointers.data());check(result==2,mode==0?"WU-local-conflict-rejected":"WU-directory-conflict-rejected");CloseHandle(rd);CloseHandle(wr);CloseHandle(event);}
 for(const auto&extra:std::vector<std::vector<std::wstring>>{{L"--unknown"},{L"--restore"},{L"--online"},{L"--online",L"--offline",L"Q:\\",L"--scan"},{L"--online",L"--scan",L"--restore"},{L"--online",L"--restore",L"--source-wim",L"none.wim"},{L"--online",L"--scan",L"--source-index",L"garbage"}}){SECURITY_ATTRIBUTES sa{sizeof(sa),nullptr,TRUE};HANDLE rd=nullptr,wr=nullptr;CreatePipe(&rd,&wr,&sa,0);HANDLE event=CreateEventW(&sa,TRUE,TRUE,nullptr);std::vector<std::wstring>a={L"test",L"--pipe",std::to_wstring(uintptr_t(wr)),L"--cancel-handle",std::to_wstring(uintptr_t(event))};a.insert(a.end(),extra.begin(),extra.end());std::vector<wchar_t*>p;for(auto&v:a)p.push_back(v.data());check(Worker(int(p.size()),p.data())==2,"malformed-worker-rejected");CloseHandle(rd);CloseHandle(wr);CloseHandle(event);}
 CloseHandle(sem);std::cout<<"cases="<<cases<<" failures="<<failures<<std::endl;return failures?1:0;}
